"""Independent simulator + exhaustive search (reference for cross-checking)."""
import itertools

def sim_tx(ops, d):
    """Apply one transaction to dict d; return new dict or None on mismatch."""
    d = dict(d)
    for op in ops:
        k = op[0]
        if k == 'get':
            if d.get(op[1]) != op[2]:
                return None
        elif k == 'put':
            d[op[1]] = op[2]
        elif k == 'del':
            d.pop(op[1], None)
        elif k == 'cas':
            _, key, old, new, want = op
            ok = d.get(key) == old
            if ok is not want:
                return None
            if ok:
                if new is None:
                    d.pop(key, None)
                else:
                    d[key] = new
        else:
            got = [[kk, vv] for kk, vv in sorted(d.items()) if op[1] <= kk < op[2]]
            if got != op[3]:
                return None
    return d

